def render_public_page(page: str, base_dir: Path, config: dict):
    if page == "Главная":
        render_home(base_dir, config)
    elif page == "Возможности":
        render_features(base_dir, config)
    elif page == "Методика":
        render_method(base_dir, config)
    elif page == "О проекте":
        render_about(base_dir, config)
    else:
        raise ValueError("Неизвестный раздел сайта")
    st.divider()
    st.caption(f"ЛесАналитика БПЛА · проект № {PROJECT_NUMBER} · демонстрационный прототип 1.3 · информация не является заключением о допустимости рубки")


